    summary: '孔子とその弟子たちの言葉や行いを、死後に弟子たちが記録した書物。仁（思いやり）と礼（社会の秩序）を説き、のちに朱熹が選んだ四書の一つとして儒教の基本経典となった。中国だけでなく朝鮮や日本の人々の考え方にも大きな影響をあたえた。',
