        text: '孔子は前551年ごろ、春秋時代の魯の国（今の山東省曲阜）に生まれた。周の王の権威が衰え、諸侯や家臣が争う時代に、周の初めの礼による秩序を理想とし、政治家として各国をめぐったが、用いられなかった。',
        talk: '孔子が生まれたのは、周の王の力がおとろえ、家臣が主君を追い出すような乱れた時代でした。貧しい家に育った孔子は、若いころから学問にはげみ、「どうすれば世の中に秩序がもどるのか」を考えつづけます。彼の答えは、昔の周の時代の礼、つまり人と人との正しいふるまい方を取りもどすことでした。孔子は弟子をつれて十数年も諸国をめぐり、王たちに自分の考えを説きましたが、どの国でも重く用いられることはありませんでした。',
        place: '曲阜（魯の都）', lon: 116.99, lat: 35.58, span: 6,
