        text: '前479年に孔子が死ぬと、弟子やその弟子たちが孔子の言葉を書きとめ、編集して『論語』ができた。全20編で、「子曰く、学びて時に之を習う、亦た説ばしからずや」で始まる。中心の教えは、家族への愛情を広げた「仁」と、その心を形に表す「礼」である。',
        talk: '『論語』は孔子が書いた本ではありません。孔子の死後、弟子たちが「先生はこうおっしゃった」と書きとめた言葉を集めたものです。最初の一節は「学んで、時々それをおさらいする。なんとうれしいことではないか」。むずかしい哲学ではなく、勉強や友だち、親への思いやりといった身近な話が多いのです。「己の欲せざる所は人に施すことなかれ」、自分がされたくないことは人にしない。この言葉は今もよく引かれます。',
