        text: '南宋の朱熹（朱子）は、『論語』『孟子』『大学』『中庸』を四書として重んじ、注釈書『四書集注』を著した。朱子学は元代の1313年に科挙の基準とされ、明・清でも科挙の試験は四書の朱熹の解釈にもとづいて出題された。',
        talk: '12世紀、南宋の学者朱熹は、たくさんある儒教の本の中から、とくに大事な4冊を選びました。『論語』はその筆頭です。朱熹がつけた解説は、やがて科挙という役人の試験の「正解」になりました。明や清の受験生は、四書を一字一句暗記し、朱熹の解釈どおりに答案を書かなければなりませんでした。つまり『論語』は、約600年もの間、中国でいちばん大事な試験の教科書だったのです。',
        place: '武夷山（福建）', lon: 117.98, lat: 27.72, span: 8,
