        text: '『論語』は朝鮮や日本にも伝わり、朝鮮王朝では朱子学が国の学問となった。日本でも江戸時代に広く読まれ、近代には実業家の渋沢栄一が『論語と算盤』を著し、道徳と経済の両立を説いた。',
        talk: '『論語』は国境をこえました。朝鮮王朝では朱子学が国の柱となり、両班たちは『論語』を暗記して科挙にのぞみました。日本でも、江戸時代の寺子屋で子どもたちが『論語』の素読をしています。おもしろいのは、近代日本の実業家渋沢栄一です。500もの会社の設立にかかわった彼は、1916年に『論語と算盤』という本を出し、「もうけることと正しい心は両立できる」と説きました。2500年前の会話が、今もビジネスの本として読まれているのです。',
