        talk: 'キリスト教の王たちは、イスラームの宮殿をこわしませんでした。その美しさを気に入り、自分たちの離宮として使ったのです。神聖ローマ皇帝でもあったカール5世は、宮殿の横に四角い新しい宮殿を建てています。その後、建物は荒れ、ナポレオン時代の戦争でも傷つきました。再び脚光を浴びたのは19世紀、アメリカの作家アーヴィングが宮殿に住んで書いた物語がきっかけです。今では、年に数百万人もの観光客がおとずれます。',
        place: 'アルハンブラ宮殿', lon: -3.59, lat: 37.18, span: 0.5,
