        year: 562, title: 'ライバルとの戦い',
        text: 'マヤには統一国家はなく、多くの都市国家が争った。562年、ティカルはカラコルに敗れ、その背後にはライバルの大都市カラクムルがいたとされる。ティカルは100年以上石碑を建てられない停滞期に入った。',
        talk: 'マヤの世界は、ひとりの皇帝がおさめる帝国ではありませんでした。ギリシアのポリスのように、たくさんの都市国家が同盟したり戦ったりしていたのです。ティカル最大のライバルは、北にある大都市カラクムルでした。562年、ティカルはカラクムルと結んだカラコルに敗れます。その後100年以上、ティカルではほとんど新しい石碑がつくられません。王の名を刻む力さえ失ってしまったのです。',
