        talk: 'チョコレートの原料カカオは、もともと中南米の植物です。それがなぜ、今は西アフリカで多くつくられているのでしょうか。19世紀、ヨーロッパではチョコレートが大人気になりました。1879年、ゴールドコーストの鍛冶職人テテ＝クワシが、出かせぎ先の島からカカオの豆を持ち帰り、自分の畑にまいたと伝えられています。カカオはよく育ち、農民たちは次々にカカオ畑を広げていきました。',
