        text: '1911年、ゴールドコーストは世界最大のカカオ生産地となった。イギリスは鉄道や港をカカオの輸送に合わせて整え、輸出の大部分をカカオが占めるようになった。食料を輸入にたよる地域も生まれた。',
        talk: 'カカオが植えられてからわずか30年あまりで、ゴールドコーストは世界一のカカオ産地になりました。植民地政府は、内陸の産地から港まで鉄道をしき、カカオを運びだしました。でも、ここに落とし穴があります。カカオで稼げるので、自分たちが食べる作物より、売るための作物を育てる人がふえたのです。国の輸出の多くが一つの作物にかたよる。これがモノカルチャー、つまり単一栽培の経済です。',
