        text: '1957年、エンクルマの指導でガーナが独立した。政府はカカオの輸出収入で工業化を進めようとしたが、1960年代半ばにカカオの国際価格が大きく下落し、財政が悪化した。1966年にはクーデタでエンクルマ政権が倒れた。',
        talk: '1957年、ガーナはサハラ以南のアフリカで、植民地からいち早く独立しました。指導者エンクルマは、カカオで稼いだお金でダムや工場をつくり、国を豊かにしようとします。ところが1960年代半ば、世界のカカオの値段が大きく下がりました。輸出の多くをカカオにたよる国にとって、これは大打撃です。財政は苦しくなり、1966年、エンクルマが外国を訪問している間に軍がクーデタをおこしました。',
