        text: '先進国と途上国の経済格差は南北問題とよばれた。途上国は資源の主権を主張し、1974年の国連資源特別総会で「新国際経済秩序（NIEO）」の樹立宣言が採択された。一次産品の価格安定や公正な貿易が求められた。',
        talk: 'ガーナのような悩みは、アフリカだけでなく、コーヒーの国、銅の国、砂糖の国など世界中にありました。工業製品の値段は上がるのに、作物や鉱物の値段は不安定で、なかなか上がりません。北の豊かな国と南の貧しい国の差は広がるばかりです。1974年、途上国は国連に集まり、資源は自分たちのものであり、貿易のルールを公正に変えるべきだと宣言しました。これが新国際経済秩序の宣言です。',
        place: 'ニューヨーク（国連本部）', lon: -73.97, lat: 40.75, span: 2,
