        talk: 'あなたが食べているチョコレートの原料の多くは、今もコートジボワールとガーナから来ています。2つの国だけで、世界のカカオの約6割です。ところが、カカオ農家の多くは、チョコレートを一度も食べたことがないともいわれます。豆を安く売るだけで、加工してもうけるのは外国の会社だからです。今では、正当な値段で買うフェアトレードや、国内でチョコレートまでつくる取り組みが始まっています。モノカルチャーからの出口を探す試みです。',
