    summary: '高麗・朝鮮王朝の支配階層。もとは朝廷で東西に並ぶ文班・武班の官僚をさしたが、朝鮮王朝では科挙を通じて官職を独占する特権身分となった。朱子学を学び、礼を重んじて社会を指導したが、のちには党争もくり返した。',
