        text: '1392年、李成桂が朝鮮王朝を建て、漢城（ソウル）を都とした。朝鮮は仏教をおさえて朱子学を国の教えとし、両班は科挙を通じて官職を独占する特権身分となった。両班の下には中人・常民・賤民がおかれた。',
        talk: '高麗の末、武将の李成桂は、改革をめざす朱子学の学者たちと手を結んで新しい王朝を開きました。朝鮮王朝です。朝鮮では、朱子学がただの学問ではなく、国の柱になりました。両班の家に生まれた男子は、幼いころから儒教の古典を学び、科挙の合格をめざします。合格して役人になれば、一族の名誉です。両班は兵役も免除され、畑仕事など体を使う労働はしないものとされました。',
