        text: '16世紀、地方の両班は書院とよばれる私設の学校を各地に建て、朱子学を学びながら勢力をもった。1575年ごろから官僚が東人と西人に分かれて争う党争が始まり、その後も派閥の対立がくり返された。',
        talk: '両班は都の役人だけではありません。地方に住む両班たちは、書院という学校を建て、尊敬する学者をまつりながら学問にはげみました。そこはやがて、同じ考えをもつ仲間の集まる拠点にもなります。16世紀の終わりごろ、役人の人事をきっかけに、両班は東人と西人という2つのグループに分かれて対立しました。学派と家柄と政治が結びついた党争は、その後200年以上も形を変えて続いていきます。',
