        text: '朝鮮後期には、商業の発達で豊かになった人々が、官職の名目を買ったり家系図（族譜）を整えたりして両班を名のるようになった。大邱の戸籍を調べた研究では、両班とされる戸の割合が18世紀から19世紀にかけて大きく増えたことが示されている。',
        talk: '身分は生まれで決まるはずなのに、朝鮮の後半になると、両班がどんどんふえていきました。なぜでしょう。商売や農業で豊かになった人々が、お金で官職の名目を手に入れたり、立派な家系図をつくったりして、両班を名のったのです。大邱という町の戸籍を調べた研究では、両班の家とされる割合が、時代とともに大きくふえていたことがわかっています。身分のしくみは、外からではなく、内側から少しずつゆらいでいました。',
