    title: '啓蒙思想 ― 理性の光で古い闇を照らす',
    period: '1748〜1789年', region: 'europe', view: 'westeurope', tags: ['sogo', 'tankyu'],
    summary: '理性を信頼し、迷信や偏見、絶対王政や身分制などの不合理を批判した18世紀ヨーロッパの思想。モンテスキュー・ヴォルテール・ルソーらが代表で、サロンや百科全書を通じて広まった。アメリカ独立革命とフランス革命を思想の面から準備した。',
