        talk: 'イングランドの議会は、こうした考えを受け入れませんでした。イングランドには、マグナ＝カルタ以来、王も法に従い、税には議会の同意がいるという伝統があったからです。チャールズ1世は議会と対立し、ついに内戦となります。そして1649年1月、ロンドンのホワイトホール宮殿の前で、王は人々の見守るなか首を切られました。神から王の位を授かったはずの人が、人民の名のもとに裁かれたのです。ヨーロッパ中に衝撃が走りました。',
