        talk: 'イギリスで王が処刑されたころ、フランスでは反対に王の力がどんどん強まっていました。その理論を支えたのが、名説教で知られた司教ボシュエです。彼は聖書の言葉をひいて、「王は神の代理人であり、王の位は神聖である」と説きました。この教えを受けたルイ14世は、豪華なヴェルサイユ宮殿に貴族たちを集め、自分を太陽にたとえました。「朕は国家なり」という言葉も有名ですが、本当に言ったかどうかは確かではありません。',
