        text: '名誉革命の後、ロックは1690年に『統治二論』を刊行し、王権神授説を批判した。政府は人々が生命・自由・財産を守るために結んだ契約によってつくられるもので、政府がこれを侵せば人々は抵抗できると説いた。',
        talk: '王の力が神からのものでないとしたら、どこから来るのでしょうか。イギリスの哲学者ロックの答えは「人々の約束から」でした。人は生まれながらに生命・自由・財産の権利をもっている。それを守るために、みんなで約束して政府をつくった。だから政府が約束を破ったら、人々は政府をかえてよい。これが社会契約説です。名誉革命の直後に出たロックの本は、王権神授説への強力な反論となり、のちにアメリカ独立宣言にも影響しました。',
