        text: 'ルイ14世の財務総監コルベールは、輸入品に高い関税をかけ、王立マニュファクチュアを設けて毛織物やガラス、ゴブラン織などの国内産業を育てた。また東インド会社を再建し、道路や運河を整えた。これをコルベール主義という。',
        talk: 'フランスでこの政策を徹底したのがコルベールです。商人の家に生まれた彼は、ルイ14世のもとで国の財政をまかされました。ヴェルサイユ宮殿の「鏡の間」の鏡をイタリアから買うと、お金が外国に出ていってしまいます。そこで彼は、ヴェネツィアから職人を招き、フランス国内で鏡をつくらせました。高級な織物も王立工場でつくり、外国製品には高い関税をかけます。こうしてためたお金が、ルイ14世の戦争と宮殿を支えたのです。',
        place: 'パリ', lon: 2.35, lat: 48.86, span: 4,
