        text: '1776年、イギリスのアダム＝スミスは『国富論（諸国民の富）』を著し、国の富は金銀ではなく労働によって生まれる生産物であると説いた。国家の規制をやめ、自由な競争にまかせるべきだとして重商主義を批判した。',
        talk: '「国の豊かさとは、金銀の量ではない」。スコットランドの学者アダム＝スミスはこう考えました。彼は、ピンをつくる工場を例にあげます。一人で全部の作業をすると1日に数本しかつくれないが、10人で作業を分担すれば4万8000本もつくれる、と。富を生むのは、人々の労働と工夫なのです。国が細かく貿易を規制するより、自由に競争させたほうが、結局みんなが豊かになる。こうして経済学が生まれ、重商主義の時代は終わりに向かいます。',
