        talk: 'キリスト教徒は、なぜローマ帝国で迫害されたのでしょうか。ローマの神々や皇帝の像に香をたいて拝むことを、彼らはこばんだからです。帝国のまとまりを強めたいディオクレティアヌス帝にとって、これは国への反逆に見えました。303年、皇帝の宮殿があったニコメディアの教会が壊されたのを皮切りに、ローマ史上最大の迫害が始まります。しかし、迫害されても信仰を守る人々の姿は、かえって新しい信者を生んでいきました。',
