        talk: 'ハギア＝ソフィアとは、ギリシア語で「聖なる知恵」という意味です。532年、首都の競技場で戦車競走を応援していた人々が、重い税への不満から暴動をおこしました。「ニカ（勝て）！」と叫んだことから、ニカの乱とよばれます。町は燃え、聖堂も焼け落ちました。ユスティニアヌス帝は一時逃げ出そうとしましたが、皇后テオドラに「帝衣は最高の死に装束です」と励まされて踏みとどまったと伝えられます。乱をおさえた皇帝は、すぐに再建を命じました。',
