        text: '数学者でもあった建築家アンテミオスとイシドロスの設計で、約1万人が働き、聖堂はわずか6年足らずで537年に完成した。直径約31m・高さ約55mのドームは、4本の巨大な柱とペンデンティブ（球面三角形）で支えられ、窓から入る光で浮かんで見えた。',
