        talk: '1054年7月のある日、礼拝の最中のハギア＝ソフィアに、ローマ教皇の使節たちが入ってきました。彼らは祭壇の上に、総主教を破門するという文書を置いて立ち去ったのです。総主教も負けずに使節たちを破門しました。こうしてキリスト教は、ローマ＝カトリック教会とギリシア正教会に分かれます。さらに1204年には、同じキリスト教徒であるはずの十字軍がこの町を占領し、聖堂の宝物をうばっていきました。',
        place: 'ハギア＝ソフィア聖堂', lon: 28.98, lat: 41.01, span: 0.3,
