        text: '1453年、オスマン帝国のメフメト2世がコンスタンティノープルを征服し、ハギア＝ソフィアはモスクに改められた。ミナレット（尖塔）が加えられ、キリスト教のモザイクは漆喰でおおわれた。この建物は、のちのオスマン帝国のモスク建築の手本となった。',
        talk: '1453年5月29日、オスマン帝国の若きスルタン、メフメト2世がコンスタンティノープルを攻め落としました。彼はまっすぐハギア＝ソフィアに向かい、ここをモスクにすると決めたと伝えられます。建物はこわされず、外にはミナレットが建てられ、壁のモザイクは漆喰でおおわれました。おもしろいことに、このドームはオスマン帝国の建築家たちの目標になります。16世紀の建築家ミマール＝スィナンは、これに負けないドームのモスクを次々に設計しました。',
