        text: 'トルコ共和国のムスタファ＝ケマルは政教分離を進め、ハギア＝ソフィアを1935年に博物館とし、モザイクの修復も行われた。2020年、トルコ政府は再びモスクとして礼拝に用いることを決め、国内外で議論をよんだ。',
        talk: 'オスマン帝国が倒れたあと、トルコ共和国の初代大統領ムスタファ＝ケマルは、宗教と政治を分ける改革を進めました。ハギア＝ソフィアは1935年に博物館となり、漆喰の下から、金色に輝くキリストやマリアのモザイクがよみがえります。キリスト教とイスラームの両方の歴史を見られる場所になったのです。しかし2020年、トルコ政府はここを再びモスクにしました。一つの建物が、いまも国の姿や宗教のあり方を映す鏡になっています。',
