        text: '663年8月、倭の水軍は錦江の河口付近の白村江で唐の水軍と戦った。唐の水軍は船の数こそ少なかったが、陣形を整えて倭の船を挟みうちにし、倭は大敗した。中国の記録は、倭の船400艘が焼かれ、煙と炎が天にみなぎり海水が赤く染まったと伝えている。',
        talk: '663年8月、白村江の河口で、倭の船団と唐の船団がぶつかりました。倭の船は数では多かったのですが、2日間の戦いのあいだ、統制のないまま次々に突っこんでいったといいます。唐の船は大きく、しっかり陣形を組んで待ちかまえていました。唐の歴史書には「倭の船400艘を焼いた。煙と炎は天をこがし、海は赤く染まった」と記されています。倭は大敗し、百済復興の望みは完全に断たれました。',
        place: '白村江（錦江河口）', lon: 126.7, lat: 36.0, span: 3,
        polities: ['yamato', 'tang', 'silla', 'baekje']
