        talk: 'もし唐の大軍が海をわたって攻めてきたら。倭の人々は本気でそれを恐れました。九州の大宰府の前には、長さ約1kmにおよぶ巨大な土の堤防、水城を築きます。島々には防人という兵士をおき、のろしで都まで知らせを送るしくみもつくりました。山の上の城を設計したのは、百済から逃げてきた技術者たちです。都も、海から遠い近江の大津に移されました。日本の歴史で、これほど外国の侵攻に備えた時代はめずらしいのです。',
        place: '水城（大宰府）', lon: 130.5, lat: 33.53, span: 4,
        polities: ['yamato'],
