        text: '668年に唐・新羅は高句麗を滅ぼし、676年には新羅が唐を追い出して半島を統一した。倭では中大兄皇子が即位して天智天皇となり、670年に全国的な戸籍の庚午年籍をつくった。701年には大宝律令が完成し、このころ国号を「日本」と定めた。',
        talk: '大敗は、倭の国を大きく変えました。強い唐に対抗するには、国じゅうの人と土地を把握し、税と兵士を集められる国にしなければなりません。天智天皇は670年、初めての全国的な戸籍をつくりました。そして701年、唐の制度にならった大宝律令が完成します。このころ、国の名も「倭」から「日本」に改められました。白村江の敗北は、日本という国が生まれるための、つらい出発点だったともいえるのです。',
