        text: '1271年に国号を元としたフビライは、大都を都とした。元ではモンゴル人のほか、中央アジア・西アジア出身者を色目人、旧金領の住民を漢人、旧南宋の住民を南人とよんだ。ただしこれは厳格な身分制度ではなかったとする見方もある。',
        talk: '色目人と聞くと、目の色がちがう人のことだと思うかもしれません。でも、それは誤解です。「色目」は「いろいろな種類」という意味で、「さまざまな種類の人々」ということなのです。元ではモンゴル人、色目人、漢人、南人という呼び分けがあり、高い役職にはモンゴル人や色目人がつきやすかったのは確かです。ただ最近の研究では、きっちりした4段階の身分制度があったわけではない、という見方も強くなっています。',
