        talk: 'フビライの財務をまかされたのは、中央アジア出身のアフマドでした。彼は塩の専売などで税収を大きくふやしましたが、取り立てが厳しく、多くの人に恨まれます。1282年、彼は都で暗殺されてしまいました。一方で、色目人は新しい学問ももたらしました。イスラームの天文学者が都に観測の器械を持ちこみ、中国の学者郭守敬は、その影響も受けながら正確な暦をつくりました。これが授時暦で、のちに日本の暦づくりにも影響をあたえます。',
