    summary: '明の洪武帝が1381年につくらせた戸籍・租税台帳。村を110戸ずつの里甲に組織し、家族や財産を10年ごとに記録して、税と労役を割り当てた。土地台帳の魚鱗図冊とともに、皇帝が全国の農民を直接つかむための道具であった。',
