        talk: '洪武帝こと朱元璋は、貧しい農民の家に生まれ、飢饉で家族を亡くし、寺の小僧として托鉢をしながら生きのびた人物です。元の末期、反乱軍に加わって頭角をあらわし、ついに皇帝になりました。そんな彼は、地主が税をごまかし、そのぶん貧しい農民が苦しむことをよく知っていました。しかも戦乱で、誰がどこに住み、どれだけの土地をもっているのか、記録はばらばらでした。国のしくみを、一から作り直す必要があったのです。',
