        text: '1387年には、土地の一筆ごとに形・面積・所有者を図示した土地台帳、魚鱗図冊がつくられた。全国から集められた黄冊は、南京の玄武湖（後湖）の島に建てられた書庫に保管され、厳重に管理された。',
        talk: '黄冊が人の台帳なら、土地の台帳もつくらなくてはなりません。1387年、田畑の一枚一枚の形を描き、広さと持ち主を書きこんだ土地台帳ができました。図にすると、細かく区切られた田畑が魚のうろこのように見えたので、魚鱗図冊とよばれます。全国から都に届いた黄冊は、南京の玄武湖に浮かぶ島の書庫におさめられました。火事やねずみから守るため、湖の島が選ばれたのです。その数は、のちに百万冊をこえたといわれます。',
