        text: '15世紀以降、人口の移動や地主の不正で、黄冊の記載は実態からはなれていった。前回の内容を写すだけの形だけの台帳も多くなった。16世紀には税を銀でまとめて納める一条鞭法が広まり、1581年に張居正のもとで全国に施行された。',
        talk: 'どんなにしっかりした台帳も、年月がたつとほころびが出てきます。農民は重い税や労役から逃げて故郷をはなれ、地主は役人にわいろを渡して土地を少なく書かせました。やがて黄冊は、前の台帳をそのまま書き写すだけになり、とうに亡くなった人がいつまでも生きていることになっている例もあったといいます。そこで16世紀、いろいろな税と労役をまとめて銀で納めさせる一条鞭法が広まりました。日本や新大陸から流れこんだ銀が、それを可能にしたのです。',
        place: '北京（明の都）', lon: 116.4, lat: 39.9, span: 8,
