        talk: 'コロンブスが最初に出会ったカリブ海の人々、タイノ人は、とても親切に一行を迎えたと記録されています。しかし翌年、1000人をこえるスペイン人が島に移り住むと、事態は一変しました。入植者たちの目的は金です。先住民には、決まった量の金を差し出すよう命じられ、できない者には厳しい罰があたえられました。スペインから遠く離れた島で、法の目も届かないまま、支配が始まっていきます。',
