        text: '1503年、イサベル女王は先住民を「自由な臣民」としながらも、入植者のもとで働かせることを認めた。エンコミエンダとは「委託」の意味で、植民者は先住民をキリスト教化し保護する義務を負うかわりに、その労働と貢納を利用できた。',
        talk: 'エンコミエンダとは、スペイン語で「任せること」という意味です。国王は入植者に「この村の先住民を任せる。キリスト教を教え、守りなさい。そのかわり、彼らを働かせてよい」と命じました。形のうえでは、先住民は奴隷ではなく、国王の自由な臣民です。でも、実際に何がおこったでしょう。入植者たちは先住民を金鉱や農園で休みなく働かせました。そこへヨーロッパから来た天然痘などの病気が重なり、島の人口はわずか数十年で激減してしまいます。',
