        talk: '1511年の待降節の日曜日、サントドミンゴの教会で、修道士モンテシーノスは入植者たちにこう語りかけました。「あなたがたは皆、大きな罪の中にいる。この人々も人間ではないのか」。教会はさわぎになりました。そのとき聞いていた人々の中に、自身もエンコミエンダで先住民を使っていたラス＝カサスがいました。彼は悩んだ末、1514年に先住民を手放し、その後50年以上、先住民を守るために国王や学者たちと戦いつづけます。',
