        talk: 'ラス＝カサスはスペインに戻り、先住民がどれほどひどい目にあっているかを国王に訴えました。その報告はのちに『インディアスの破壊についての簡潔な報告』として出版されます。1542年、国王カール5世はインディアス新法を出し、先住民を奴隷にすることや、新しくエンコミエンダをあたえることを禁じました。しかし、利益を失う入植者たちは猛反発し、ペルーでは反乱までおこります。遠い本国の法律を現地で守らせるのは、とても難しいことでした。',
