        talk: 'エンコミエンダが弱まっても、先住民の苦しみが終わったわけではありません。アンデスのポトシ銀山では、村ごとに順番で男たちを鉱山に送るミタ制のもと、多くの人が過酷な労働で命を落としました。また、大地主が農民を借金でしばりつけて働かせるアシエンダという大農園も広がります。そして、減ってしまった先住民のかわりに、アフリカから大勢の人々が奴隷として運ばれてきました。今のラテンアメリカの社会の成り立ちは、この歴史と切りはなせないのです。',
