        talk: 'イギリス国教会の始まりには、意外な理由がありました。王の離婚です。ヘンリ8世の王妃キャサリンはスペインの王女で、2人の間には娘メアリしか育ちませんでした。王位を男子に継がせたいヘンリは、侍女のアン＝ブーリンと結婚したいと考え、教皇に「最初の結婚は無効だった」と認めてもらおうとします。ところが、キャサリンの甥は、ローマを軍で押さえていた皇帝カール5世でした。教皇は、首を縦にふれなかったのです。',
