        text: '1517年、ヴィッテンベルク大学の神学教授ルターは、贖宥状（免罪符）の販売を批判する「九十五か条の論題」を発表した。ルターの主張は印刷物で広がり、教皇や皇帝カール5世と対立した諸侯の中に彼を支持する者が現れた。',
