        talk: 'ルター派の諸侯たちは、皇帝に対抗するために同盟を結びました。カール5世は、フランスやオスマン帝国との戦いに追われて手が回りませんでしたが、1546年、ついに同盟との戦争に乗り出します。翌年の戦いで皇帝は大勝しました。ところが、皇帝側についていたザクセンのモーリッツ公が裏切り、1552年に皇帝を急襲します。カール5世はアルプスの山道を逃げのびるはめになりました。もはや力でルター派を押さえこむことはできなかったのです。',
