        text: '1555年、アウクスブルクの帝国議会で和議が結ばれた。諸侯と帝国都市はカトリックとルター派のどちらかを選ぶことができ、領民は領主の選んだ宗派に従うこととされた。ただし、別の宗派の領地へ移住する権利は認められた。',
        talk: '1555年9月、南ドイツの商業都市アウクスブルクで、皇帝の弟フェルディナントの立ち会いのもと、和議が結ばれました。のちに「領主の宗教が、その地の宗教」とまとめられた原則です。ザクセンの領主がルター派を選べば、ザクセンの人々はルター派になる。それがいやな人は、荷物をまとめて別の領地に引っ越すしかありません。つまり、宗教を選ぶ自由をもったのは個人ではなく、領主だったのです。そしてカルヴァン派は、そもそも選択肢に入っていませんでした。',
