        talk: 'カール5世は、スペインからドイツ、ネーデルラント、イタリア、そしてアメリカ大陸まで支配した大帝国の主でした。彼の夢は、一つのカトリックの信仰のもとに、キリスト教世界をまとめることでした。アウクスブルクの和議は、その夢が破れたことを意味します。翌1556年、疲れはてた皇帝は退位し、スペインの修道院のそばで静かな晩年を過ごしました。大帝国は、弟と息子に分けてゆずられます。',
