        talk: '陸で負け続けた朝鮮を救ったのは、海の名将・李舜臣でした。彼は、屋根を鉄のとげでおおったといわれる亀甲船や、地形と潮の流れを生かした作戦で、日本の水軍を次々に破ります。1592年夏の閑山島沖の海戦では、鶴が翼を広げたような陣形で敵を囲みこみました。海の道を断たれた日本軍は、食料や武器が届かなくなります。各地では農民や僧侶が義兵として立ち上がり、翌年には明の大軍が平壌を取りもどしました。',
        place: '閑山島', lon: 128.48, lat: 34.77, span: 4,
