        text: '朝鮮では多くの人が死に、田畑は荒れはてた。日本には多くの朝鮮人が連れ去られ、その中の陶工たちが有田焼などを始めた。明は戦費で財政が悪化し、のちの女真の台頭を許した。徳川政権は朝鮮との国交を回復し、1607年から朝鮮通信使が来日した。',
        talk: '7年にわたる戦争は、朝鮮の国土を深く傷つけました。また、たくさんの朝鮮の人々が日本に連れ去られています。その中には陶磁器の職人もいて、九州の有田焼などは、彼らの技術から生まれました。援軍を送った明も、ばく大な戦費で財政が苦しくなり、北の女真人ヌルハチが力をのばすすきをあたえます。秀吉の死後、日本の徳川家康は朝鮮と和解し、1607年から朝鮮通信使が江戸を訪れるようになりました。',
