        text: 'オスマン帝国の命令を受けたエジプトのムハンマド＝アリーは軍を送り、聖地を奪回した。1818年、その子イブラーヒームの軍がディルイーヤを陥落させ、ワッハーブ王国は滅んだ。しかしサウード家はその後も再興をはかった。',
        talk: 'オスマン帝国のスルタンは、自分では軍を送る余裕がなく、エジプトの実力者ムハンマド＝アリーに討伐を命じました。近代的な軍隊を育てていたエジプト軍は、聖地を取りもどし、砂漠の奥深くまで進みます。1818年、ついに都ディルイーヤが落ち、ワッハーブ王国は滅びました。ディルイーヤの町は破壊され、今もその遺跡が残っています。けれども、サウード家とワッハーブ派の結びつきは消えず、その後も何度も国の再建が試みられました。',
        place: 'ディルイーヤ', lon: 46.57, lat: 24.73, span: 8,
        people: ['muhammad-ali'], polities: ['wahhabi', 'egypt-ma', 'ottoman']
