        text: '20世紀初め、イブン＝サウードは1902年にリヤドを奪回し、アラビア半島の大部分を統一して、1932年にサウジアラビア王国を建てた。ワッハーブ派の教えは国の基本となった。1938年には大油田が発見された。',
        talk: '1902年、亡命先から戻った若きイブン＝サウードは、わずかな仲間とともにリヤドの砦を奇襲して取りもどしました。そこから30年かけて半島の大部分をまとめ、1932年、自分の家の名をつけたサウジアラビア王国を建てます。サウード家のアラビア、という意味です。6年後には砂漠の下から巨大な油田が見つかり、国は大きく変わっていきました。なお「ワッハーブ派」は外からの呼び名で、信奉者たちは自らを「唯一神を信じる者」とよびます。',
        place: 'リヤド', lon: 46.72, lat: 24.69, span: 10,
