        talk: '6月18日の朝、戦場はぬかるんでいました。前の晩に大雨が降ったため、ナポレオンは地面がかわくのを待ち、大砲での攻撃を昼近くまで遅らせます。この数時間が運命を分けました。丘の上で守りを固めるウェリントンの軍を攻めあぐねているうちに、午後、東からプロイセン軍が現れたのです。夕方、ナポレオンは最後の切り札、近衛隊を突撃させますが、退けられます。ウェリントンは「生涯でいちばんの接戦だった」と語ったといわれます。',
        place: 'ワーテルロー', lon: 4.41, lat: 50.68, span: 0.6,
