        talk: 'パリに戻ったナポレオンは、4日後に二度目の退位をしました。イギリスは、もう二度と逃げられない場所を選びます。アフリカ大陸から約2000kmもはなれた大西洋の孤島、セントヘレナです。ナポレオンはここで回想録を口述しながら、6年近くを過ごし、1821年に亡くなりました。ヨーロッパでは、フランス革命前の王家と秩序を正しいものとするウィーン体制が始まります。でも、自由と国民という革命の考えは、もう消し去ることはできませんでした。',
