        talk: 'パリの革命から3週間後、ウィーンでも学生や労働者が立ち上がりました。30年以上もヨーロッパの秩序を守ってきたメッテルニヒは、宰相を辞め、ロンドンへ逃げます。彼は変装して逃げたとも伝えられています。数日後にはベルリンでもバリケード戦がおこり、プロイセン王は憲法をつくると約束しました。オーストリア帝国の中では、ハンガリー人やチェック人が、自分たちの民族の権利を求めて声をあげます。まさに「諸国民の春」でした。',
