        talk: 'ドイツはまだ、たくさんの国に分かれていました。1848年5月、フランクフルトの教会に、ドイツ各地から選ばれた代表が集まります。教授や弁護士が多く、「教授たちの議会」ともよばれました。1年近くかけて立派な憲法をつくり、プロイセン王をドイツ皇帝に選びます。ところが王は、民衆の議会からさしだされた王冠など受けられない、という意味のことを言って断りました。話しあいによるドイツ統一の夢は、ここで破れます。同じ年、ロンドンではマルクスらの『共産党宣言』も出されていました。',
