        talk: '春の熱気は長く続きませんでした。パリでは6月、仕事を失った労働者の蜂起が軍によって鎮圧され、12月には人気の高いナポレオンのおい、ルイ＝ナポレオンが大統領に選ばれます。ハンガリーの独立も、ロシア軍の助けを借りたオーストリアに押しつぶされました。では、1848年の革命はむだだったのでしょうか。いいえ。オーストリアでは農民が領主から解放され、人々は国民や民族という考えを知りました。それは、のちのイタリアやドイツの統一へとつながっていきます。',
