        talk: 'スラヴ人とは、ロシア人、ポーランド人、チェック人、セルビア人、ブルガリア人など、よく似た言葉を話す人々のことです。19世紀、その多くはオーストリアやオスマン帝国に支配されていました。チェックの学者たちは、忘れられかけていた自分たちの言葉で辞書や歴史書をつくり、民族の誇りをとりもどそうとします。1848年の革命のさなか、プラハにはスラヴ各地の代表が集まりました。「われわれスラヴ人は兄弟だ」。その思いがパン＝スラヴ主義の出発点です。',
