        talk: 'クリミア戦争に敗れ、黒海への進出を阻まれたロシア。目を向けたのは、オスマン帝国の支配下にあるバルカン半島のスラヴ人たちでした。同じスラヴ人で、同じ正教会を信じる兄弟を、異教徒の支配から救い出そう。ロシアの思想家たちは、ロシアこそスラヴ世界の中心だと説きます。その主張は、凍らない港を求めて南へ進みたいロシア政府にとって、とても都合のよいものでした。理想と国益が、ここで重なりあったのです。',
