        text: '1876年、茨城県や三重県などで地租改正に反対する大規模な一揆がおこった。士族の反乱も続くなか、政府は1877年に地租を地価の2.5％に引き下げた。「竹槍でドンと突き出す二分五厘」とうたわれた。',
        talk: '1876年の暮れ、三重県で始まった一揆は、愛知や岐阜にまで広がり、数万人が参加したといわれます。ちょうど西日本では、不満をもつ士族の反乱もあいついでいました。農民と士族が手を結んだら大変です。政府は1877年のはじめ、地租を3％から2.5％に下げました。人々は「竹槍でドンと突き出す二分五厘」とうたいました。竹槍をもって立ち上がったから、2.5％まで下げさせた、という意味です。',
