        text: '地租は明治前期の国の税収の大部分を占め、近代化を財政面から支えた。一方、土地を手放した農民は小作人となり、地主に収穫の約半分を現物の小作料として納めた。この地主制は第二次世界大戦後の農地改革（1946〜47年ごろから）で解体された。',
        talk: '地租は明治のはじめ、国の税収の大部分を占め、工場や鉄道、軍隊をつくるお金になりました。でも、その陰で苦しんだ人々もいます。現金で税をはらえず土地を手放した農民は、地主から土地を借りる小作人になりました。小作人は、とれた米の半分ほどを地主に納めなければなりません。地主は税を現金ではらい、米を売ってもうけます。この大きな格差がなくなるのは、第二次世界大戦後の農地改革を待たなければなりませんでした。',
