        talk: '孫文は、少年時代をハワイで過ごしました。そこで見たのは、選挙で代表を選び、法律で動く社会です。故郷の清とは、まるでちがいました。香港で医者になった彼は、「人の病気を治すより、国の病気を治したい」と考えるようになります。1894年、日清戦争のさなか、ハワイで仲間と興中会をつくり、清朝を倒す革命をめざしました。翌年の広州での蜂起はすぐに失敗し、孫文は首に懸賞金をかけられて、世界を逃げまわる身になります。',
