        text: '1916年6月、フサインはオスマン帝国に対して反乱をおこした（アラブ反乱）。イギリスの将校ロレンスも協力し、フサインの子ファイサルらの軍は1917年にアカバを占領し、1918年にはダマスクスに入った。',
        talk: '1916年6月、フサインはオスマン帝国に反旗をひるがえしました。息子のファイサルが率いるアラブの部隊は、ラクダで砂漠を進み、ヒジャーズ鉄道を爆破してオスマン軍を苦しめます。これを助けたのが、のちに映画『アラビアのロレンス』で有名になるイギリスの若い将校ロレンスでした。1917年には紅海の港アカバを、陸の側から奇襲して落とします。1918年秋、アラブの軍はダマスクスに入りました。独立の夢は、もう手の届くところにあるように見えました。',
        place: 'アカバ', lon: 35.0, lat: 29.53, span: 8,
        polities: ['ottoman'],
        marks: [{ name: 'ダマスクス', lon: 36.29, lat: 33.51 }, { name: 'メディナ', lon: 39.61, lat: 24.47 }]
