        talk: '戦争が終わっても、約束された広いアラブの独立国は生まれませんでした。1920年、アラブの地は、国際連盟の委任統治という名で、イギリスとフランスに分けられます。シリアの王を名のったファイサルはフランス軍に追い出され、その後イギリスによってイラクの国王にすえられました。そしてパレスチナには、ユダヤ人の移民がふえていき、もとから住むアラブ人との争いが始まります。100年前の矛盾した約束は、今も解決されない問題として残っているのです。',
