        talk: '第一次世界大戦は、陸の塹壕戦だけではありませんでした。海の上でも、相手の国を飢えさせる戦いが行われていたのです。世界一の海軍をもつイギリスは、ドイツへ向かう船をとめ、食料も原料も入らないようにしました。水上の艦隊では勝ち目のないドイツが目をつけたのは、新しい兵器、潜水艦です。海の中から近づき、魚雷でイギリスへ物資を運ぶ商船をしずめる。イギリスもまた、島国として輸入にたよる国だったからです。',
