        talk: '1915年5月7日、ニューヨークからイギリスに向かっていた豪華客船ルシタニア号が、アイルランドの沖で魚雷を受けました。船はわずか18分ほどでしずみ、乗っていた人のうち約1200人が亡くなります。その中には128人のアメリカ人がいました。中立を守っていたアメリカの人々は激しく怒ります。ドイツは、船が武器を運んでいたと主張しましたが、アメリカとの戦争はさけたいと考え、警告なしの攻撃をひかえるようになりました。',
