        talk: '大戦が終わっても、海の上では新しい競争が始まっていました。アメリカ、イギリス、日本が、次々に巨大な戦艦をつくっていたのです。日本は戦艦8隻と巡洋戦艦8隻をそろえる八八艦隊計画を進め、軍艦をつくるお金が国の予算の約3分の1にのぼった年もありました。このままでは、どの国も財政がもちません。さらにアメリカは、大戦中に中国での権益をのばした日本を警戒していました。そこでアメリカの大統領ハーディングが、会議を呼びかけます。',
