        talk: '1921年11月、ワシントンに9か国の代表が集まりました。初日、議長のアメリカ国務長官ヒューズが演説を始めます。ふつうはあいさつで終わるはずの開会演説で、彼は「アメリカは建造中の戦艦15隻をふくむ30隻を廃棄する。イギリスはこれとこれを、日本はこれとこれを」と、各国の軍艦の名前を次々に読み上げたのです。会場は大さわぎになりました。ある記者は「ヒューズは35分で、世界の提督たちが何百年かけても沈められなかった数の軍艦を沈めた」と書いたといわれます。',
