        talk: '会議ではいくつもの条約が結ばれました。まず四か国条約で、太平洋の島々の現状を守ることが約束され、20年続いた日英同盟は終わりました。次に海軍軍備制限条約。戦艦などの主力艦の量は、アメリカとイギリスが5なら日本は3と決まります。日本の海軍の中には「7割は必要だ」という強い不満がありました。そして九か国条約で、中国の領土と主権を尊重することが決められ、日本は山東省で得た権益を中国に返しました。',
