        talk: '条約が結ばれると、つくりかけの戦艦はどうなったのでしょう。多くはスクラップにされたり、射撃の的としてしずめられたりしました。ところが、例外も認められていました。空母への改造です。日本では、巡洋戦艦になるはずだった赤城と、戦艦になるはずだった加賀が、飛行機をのせる空母に生まれかわります。皮肉なことに、軍縮のための条約が、空母という新しい兵器の時代を早めることになりました。20年後、この2隻は真珠湾攻撃に参加します。',
