        talk: '1920年代、日本の外交は、アメリカやイギリスと協調する方向に進みました。軍事費が減り、国民の暮らしにも余裕が生まれます。けれども、海軍の中には、比率に不満をもつ人々がいました。1931年の満洲事変で、日本は中国の領土に軍を進め、九か国条約の約束を自ら破ります。1934年には軍縮条約から抜けることを通告し、条約は1936年の終わりに効力を失いました。再び始まった建艦競争の中で、日本は巨大戦艦大和の建造に取りかかります。',
