        talk: '1890年、日本で初めての衆議院議員の選挙が行われました。ところが、投票できたのは、税金を年に15円以上納める25歳以上の男性だけ。今のお金で何十万円もの税金をはらう、地主やお金持ちだけです。その数は約45万人、人口のわずか1％ほどでした。選挙のたびに、条件は少しずつゆるめられ、1919年には3円になります。それでも、都市で働く労働者や、小作人の多くは選挙権をもてませんでした。',
