        talk: '1929年、アメリカから始まった世界恐慌は、ドイツを直撃しました。工場は止まり、1932年には働く人のおよそ3人に1人が仕事を失います。議会では政党どうしがいがみあい、何も決められません。そんななか、「強い指導者がドイツを立て直す」とうったえたのがヒトラーのナチ党でした。ヴェルサイユ条約への怒り、共産主義へのおそれ、そして生活の不安。1932年7月の選挙で、ナチ党は37％の票を集め、第一党になりました。',
