        talk: '燃えた議事堂のかわりに使われたのは、オペラ劇場でした。3月23日、会場の中も外も、ナチ党の突撃隊員がとりかこんでいます。この法律は、政府が議会を通さずに法律をつくれる、しかも憲法に反してもよい、という内容でした。社会民主党の党首ヴェルスは、おどしの声が飛ぶ中で立ち上がり、「自由と生命は奪えても、名誉は奪えない」と反対演説をします。それでも結果は444対94。議会は、自分の手で自分の力を手放したのです。',
        place: 'クロル＝オペラ座（ベルリン）', lon: 13.37, lat: 52.52, span: 0.4,
