        text: 'ガンディーやネルーの国民会議派は、宗教をこえた統一インドの独立をめざした。一方、ジンナーの率いる全インド＝ムスリム連盟は、ムスリムが少数派として不利になることを警戒し、1940年のラホール大会でムスリムの独立国家パキスタンの建設を目標にかかげた。',
        talk: 'インドの独立運動には、大きな問いがありました。独立したあと、この国はどんな国になるのか。ガンディーやネルーの国民会議派は、ヒンドゥー教徒もムスリムも一緒に暮らす一つのインドを考えていました。しかし、人口の約4分の1にあたるムスリムの指導者ジンナーは、「数の多いヒンドゥー教徒の国の中で、ムスリムは少数派として押さえつけられる」と警戒します。1940年、ムスリム連盟はラホールで、ムスリムの国パキスタンをつくることを目標に決めました。',
