        talk: '国境が決まると、人類の歴史でも最大級の人の移動が始まりました。パンジャーブでは、家も畑も捨てた人々が、牛車や徒歩、満員の列車で国境をこえていきます。その途中で、宗教のちがう人々による襲撃がくり返されました。死者は数十万から100万人以上と推定されています。78歳のガンディーは、暴動の町に入り、断食をして「殺しあいをやめよ」と訴えました。しかし1948年1月30日、彼はムスリムに甘すぎると考えたヒンドゥー教徒の青年に撃たれました。',
