        text: 'ヒンドゥー教徒の藩王がおさめムスリムが多数を占めたカシミールの帰属をめぐり、1947年に第1次インド＝パキスタン戦争がおこった。カシミール問題は今も続いている。1971年には東パキスタンがバングラデシュとして独立した。',
        talk: '分離独立の傷は、その後も消えませんでした。北のカシミール地方は、住民の多くがムスリムなのに、王はヒンドゥー教徒でした。王がインドへの帰属を決めると、パキスタンとの戦争になります。カシミールは今も、両国が自分の領土だと主張する対立の場所です。また、1600kmもはなれた東パキスタンでは、言葉も文化もちがう西の支配への不満が高まり、1971年、バングラデシュとして独立しました。宗教だけで一つの国をつくることの難しさを示しています。',
