        talk: '1940年代の終わり、アジアには2つの新しい大国が生まれました。イギリスから独立したインドと、内戦に勝った共産党の中華人民共和国です。インドのネルーは、アメリカにもソ連にもつかない中立の道を歩もうとし、新しい中国を早くから認めました。ところが1950年、中国の軍隊が、インドと国境を接するチベットに入ります。ヒマラヤをはさんで向きあう2つの大国は、どうつきあっていけばよいのでしょうか。',
