        text: '1954年4月、中国とインドはチベット地方との通商・交通に関する協定を結び、その前文に5つの原則を記した。（1）領土・主権の相互尊重、（2）相互不可侵、（3）内政不干渉、（4）平等互恵、（5）平和共存である。',
        talk: '1954年4月、北京で中国とインドの協定が結ばれました。中身はチベットとの商売や巡礼についての細かい取り決めでしたが、その前文に5つの原則が書かれていました。おたがいの領土と主権を尊重する。攻めこまない。相手の国の中のことに口を出さない。対等な立場で、ともに利益を得る。そして、平和に共存する。どれも当たり前に聞こえますが、大国が小国を支配してきたアジアの国々にとっては、とても大切な約束でした。',
