        talk: '1954年の初夏、中国の周恩来首相は、インドシナの戦争を話しあうジュネーヴ会議の合間をぬって、デリーを訪れました。ネルーと周恩来は、5つの原則を、中国とインドの間だけでなく、世界のすべての国の関係に当てはまるものだと宣言します。その足で周恩来はビルマにも向かいました。当時インドでは「インド人と中国人は兄弟」という言葉が流行したといいます。冷戦のまっただなか、アジアから新しい声があがったのです。',
