        talk: '翌1955年、平和五原則はさらに広がりました。インドネシアのバンドンに集まったアジア・アフリカの29か国は、この5つをもとに、人権の尊重や国連憲章の尊重などを加えた平和十原則をまとめます。米ソのどちらかにつくのではなく、植民地から独立した国々どうしが手をつなぐ。この考えは、1961年にユーゴスラヴィアのベオグラードで開かれる非同盟諸国首脳会議へと引きつがれていきました。',
