        text: '1961年、ソ連のガガーリンが人類初の有人宇宙飛行に成功した。アメリカのケネディ大統領は同年、1960年代のうちに人間を月に送ると宣言し、1969年にアポロ11号が月面着陸を果たした。',
        talk: '競争はさらに続きます。1961年4月、ソ連のガガーリンが人類で初めて宇宙を飛び、「地球は青かった」という言葉で知られるようになりました。くやしがったケネディ大統領は、その年、「1960年代のうちに人間を月に送り、無事に帰還させる」と宣言します。そして1969年7月、アポロ11号のアームストロングが月面に第一歩をしるしました。スプートニクからわずか12年。今、私たちが使う天気予報やGPSも、この競争から生まれた技術の上にあります。',
